const item = $input.first();
const body = item.json.body ?? {};

const required = [
  'orderCode', 'name', 'phone', 'moderatorName',
  'fulfillmentMethod', 'deliveryDate', 'deliveryTimeFrom',
  'cakeType', 'cakeSize'
];

for (const field of required) {
  if (body[field] === undefined || body[field] === null || String(body[field]).trim() === '') {
    throw new Error(`Missing required field: ${field}`);
  }
}

const numericFields = [
  'numberOfTiers',
  'basePriceEGP',
  'cakeDesignExtraEGP',
  'addOnsTotalEGP',
  'deliveryFeeEGP',
  'discountInputValue',
  'discountAmountEGP',
  'totalOrderEGP'
];

const order = { ...body };

for (const field of numericFields) {
  const value = order[field];
  if (value === undefined || value === null || value === '') {
    order[field] = 0;
    continue;
  }

  const parsed = Number(value);
  if (!Number.isFinite(parsed)) {
    throw new Error(`Invalid numeric value: ${field}`);
  }
  order[field] = parsed;
}

for (const field of ['dimensions', 'city', 'area', 'addressDetails', 'deliveryTimeTo', 'details']) {
  if (order[field] === '') order[field] = null;
}

if (typeof order.addOns === 'string') {
  try {
    order.addOns = JSON.parse(order.addOns || '[]');
  } catch {
    throw new Error('The addOns field contains invalid JSON');
  }
}
if (!Array.isArray(order.addOns)) {
  throw new Error('The addOns field must be an array');
}

for (const [index, addon] of order.addOns.entries()) {
  if (!addon.productId || !addon.productName || !addon.unit) {
    throw new Error(`Invalid add-on at position ${index + 1}`);
  }
  for (const key of ['quantity', 'unitPriceEGP', 'designExtraEGP', 'totalEGP']) {
    const value = Number(addon[key] ?? 0);
    if (!Number.isFinite(value)) {
      throw new Error(`Invalid add-on ${key} at position ${index + 1}`);
    }
    addon[key] = value;
  }
}

if (!['delivery', 'pickup'].includes(order.fulfillmentMethod)) {
  throw new Error('fulfillmentMethod must be delivery or pickup');
}
if (!['none', 'percentage', 'amount'].includes(order.discountType)) {
  throw new Error('discountType must be none, percentage or amount');
}

return [{
  json: order,
  binary: item.binary ?? {}
}];

const item = $input.first();
const orderId = item.json.order_id;
const orderCode = item.json.order_code;

if (!orderId) throw new Error('The saved order_id was not returned by PostgreSQL.');

const binary = item.binary ?? {};
const imageProps = Object.keys(binary).filter((key) =>
  /^(cakeImage|depositImage)_\d+$/i.test(key)
);

if (imageProps.length === 0) {
  throw new Error('No cakeImage_* or depositImage_* binary images were received. Order was saved, but image upload cannot continue.');
}

const result = [];

for (let index = 0; index < imageProps.length; index++) {
  const property = imageProps[index];
  const imageType = property.toLowerCase().startsWith('cakeimage') ? 'cake' : 'deposit';
  const original = binary[property];
  const originalName = original.fileName || `${property}.jpg`;
  const safeName = originalName.replace(/[^a-zA-Z0-9._-]/g, '_');
  const mimeType = original.mimeType || 'application/octet-stream';
  const buffer = await this.helpers.getBinaryDataBuffer(0, property);

  const objectKey = `orders/${orderId}/${imageType}/${property}_${safeName}`;

  result.push({
    json: {
      orderId,
      orderCode,
      sourceBinaryProperty: property,
      imageType,
      fileName: originalName,
      objectKey,
      mimeType,
      fileSizeBytes: buffer.length
    },
    binary: { data: original }
  });
}

return result;

const rows = $input.all();
if (rows.length === 0) throw new Error('No image metadata rows were saved.');

const orderId = rows[0].json.order_id;
const uploaded = rows.length;
const byType = rows.reduce((acc, row) => {
  const type = row.json.image_type;
  acc[type] = (acc[type] || 0) + 1;
  return acc;
}, {});

return [{
  json: {
    success: true,
    orderId,
    imagesUploaded: uploaded,
    cakeImagesUploaded: byType.cake || 0,
    depositImagesUploaded: byType.deposit || 0,
    imageUploadStatus: 'success',
    verifiedBy: 'S3 Upload operation completed successfully and image metadata was saved in PostgreSQL'
  }
}];

const monthly = $('Append monthly ').all();
const allOrders = $input.all();
function inspect(items) {
  const errors = items.filter(x => x.json?.error || x.json?.errorMessage);
  return { success: errors.length === 0, errors: errors.map(x => String(x.json.errorMessage || x.json.error?.message || x.json.error)) };
}
const m = inspect(monthly);
const a = inspect(allOrders);
return [{ json: { sheets: { success: m.success && a.success, monthly: m, allOrders: a } } }];

const d = $input.first().json;
const sheets = d.sheets || { success: false, monthly: {success:false, errors:['No Google Sheets result']}, allOrders: {success:false, errors:['No Google Sheets result']} };
const images = d.images || {
  status: d.imageUploadStatus || 'success',
  imagesUploaded: Number(d.imagesUploaded || 0),
  cakeImagesUploaded: Number(d.cakeImagesUploaded || 0),
  depositImagesUploaded: Number(d.depositImagesUploaded || 0)
};
const warnings = [];
if (!sheets.success) warnings.push('Order saved in PostgreSQL, but one or more Google Sheets updates failed.');
if (images.status === 'failed') warnings.push('Order saved, but one or more image uploads failed.');
return [{ json: {
  success: true,
  orderSaved: true,
  orderId: d.orderId || d.order_id,
  orderCode: d.orderCode || d.order_code,
  googleSheets: sheets,
  images,
  warnings,
  status: warnings.length ? 'partial_success' : 'success'
} }];
